import json, urllib.request
base = "http://127.0.0.1:6333/collections/compliance_context_v1/points/scroll"
def post(body):
    req = urllib.request.Request(base, data=json.dumps(body).encode(), headers={"Content-Type":"application/json"})
    with urllib.request.urlopen(req, timeout=15) as r:
        return json.load(r)
# keys-only: no vectors, include candidate join keys + meta, exclude bulky text
include = ["group_id","logical_id","source_hash","text_hash","schema_version","members","paths","part","total_chunks","mapping_id","subid","generation","direction","collection","context_hash","record"]
offset = None
key_counts, n, examples = {}, 0, {}
while True:
    body = {"limit": 100, "with_vector": False, "with_payload": {"include": include}}
    if offset is not None:
        body["offset"] = offset
    try:
        res = post(body)
    except Exception as e:
        print("SCROLL_ERROR", type(e).__name__, str(e)[:200])
        break
    pts = res.get("result", {}).get("points", [])
    if not pts:
        break
    for p in pts:
        n += 1
        pay = p.get("payload", {}) or {}
        for k in pay.keys():
            key_counts[k] = key_counts.get(k, 0) + 1
        for jk in ("mapping_id","subid","generation","direction","collection","context_hash","record"):
            if jk in pay and jk not in examples:
                examples[jk] = str(pay[jk])[:160]
    offset = res.get("result", {}).get("next_page_offset")
    if offset is None:
        break
    if n > 5000:
        break
print("POINTS_SCROLLED", n)
print("KEY_COUNTS", json.dumps(key_counts, indent=1, sort_keys=True))
print("JOIN_KEY_EXAMPLES", json.dumps(examples, indent=1, sort_keys=True))

