[crates/op-grpc-bridge/src/chain_vector_projector.rs#07C5]
1://! Vectorize on mutation (OD-64).
2://!
3://! Every committed chain event is already a Snowball timing block. This
4://! projector turns each block into a vector as soon as it lands — chain first
5://! (`vectors/` subvolume, sidecar with host load and latencies), Qdrant on
6://! the replica after `btrfs receive`, or on the origin only under the
7://! explicit `OPDBUS_CHAIN_VECTORS_UPSERT_ORIGIN=1` exception the existing
8://! design reserves for manual use.
9://!
10://! The noise filter is the **sealed plugin schema that created the data**
11://! ([`SchemaProjectionPolicy`]): the embedding text is the method's (or
12://! signal's) schema-described arguments with the descriptions the schema
13://! author wrote, `x-secret` and `x-opdbus-private` fields dropped, undeclared
14://! keys ignored. Hashes,
15://! event ids, raw timestamps and identity metadata stay out of the text and
16://! go to the Qdrant payload as allow-listed filters.
17://!
18://! Failure posture: a mutation is durable before its vector exists, so an
19://! embedder or Qdrant outage delays the index and never the control plane;
20://! the projector retries loudly and `project_pending` drains the backlog.
21:
22:use std::collections::HashMap;
23:use std::sync::Arc;
24:use std::time::{Duration, Instant};
25:
26:use op_cognitive::chain_vectors::{ChainVectorIndex, ProjectionPolicy};
27:use op_snowball::ChainBlockRef;
28:use op_state_store::schema_projection::described_fields;
29:use tokio::sync::{Mutex, Notify};
30:
31:/// Blocks embedded per pass.
32:const PASS_LIMIT: usize = 256;
33:/// Sweep even without a wake, so a missed notify cannot strand a block.
34:const SWEEP_EVERY: Duration = Duration::from_secs(30);
35:/// Back-off after the index could not be opened or a pass failed.
36:const RETRY_AFTER: Duration = Duration::from_secs(60);
37:/// Sealed schema cache lifetime inside the policy.
38:const SCHEMA_TTL: Duration = Duration::from_secs(30);
39:
40:/// A cached sealed schema (or a cached miss) with the time it was read.
41:type CachedSchema = (Instant, Option<Arc<op_state_store::PluginSchema>>);
42:
43:/// The bridge's noise filter: sealed schema of `(plugin, method|signal)`.
44:pub struct SchemaProjectionPolicy {
45:    catalog: std::path::PathBuf,
46:    cache: std::sync::Mutex<HashMap<String, CachedSchema>>,
47:}
48:
49:impl SchemaProjectionPolicy {
50:    pub fn new(catalog: std::path::PathBuf) -> Self {
51:        Self {
52:            catalog,
53:            cache: std::sync::Mutex::new(HashMap::new()),
54:        }
55:    }
56:
57:    fn schema(&self, plugin: &str) -> Option<Arc<op_state_store::PluginSchema>> {
58:        let mut cache = self.cache.lock().unwrap_or_else(|e| e.into_inner());
59:        if let Some((at, schema)) = cache.get(plugin)
60:            && at.elapsed() < SCHEMA_TTL
61:        {
62:            return schema.clone();
63:        }
64:        let schema = crate::sealed_schema_reader::read_manifest_pinned_schema_document(
65:            &self.catalog,
66:            plugin,
67:        )
68:        .ok()
69:        .map(|pinned| Arc::new(pinned.schema));
70:        cache.insert(plugin.to_string(), (Instant::now(), schema.clone()));
71:        schema
72:    }
