74:    /// The schema-described lines for a block, or `None` when the plugin is
75:    /// not sealed (retired/unknown): then only the header is embedded.
76:    fn lines_for(&self, block: &ChainBlockRef) -> (Vec<(String, String)>, Option<String>) {
77:        let mut lines = Vec::new();
78:        let Some(schema) = self.schema(&block.category) else {
79:            return (lines, None);
80:        };
81:        let data: serde_json::Value =
82:            simd_json::serde::from_owned_value(block.data.clone()).unwrap_or_default();
83:        let payload = &data["payload"];
84:        let input = payload
85:            .get("input_payload")
86:            .cloned()
87:            .unwrap_or(serde_json::Value::Null);
88:        lines.push((
89:            "plugin".into(),
90:            format!(
91:                "{} — {}",
92:                schema.display_name.as_deref().unwrap_or(&schema.name),
93:                schema.description
94:            ),
95:        ));
96:        let (args_schema, subid, kind) = if let Some(method) = schema.methods.get(&block.action) {
97:            let args: serde_json::Value =
98:                simd_json::serde::from_owned_value(method.args.clone()).unwrap_or_default();
99:            (Some(args), Some(method.subid.clone()), "method")
100:        } else if let Some(signal) = schema.signals.iter().find(|s| s.name == block.action) {
101:            let args = signal.payload.clone().map(|p| {
102:                simd_json::serde::from_owned_value::<serde_json::Value>(p).unwrap_or_default()
103:            });
104:            (args, Some(signal.subid.clone()), "signal")
105:        } else {
106:            (None, None, "operation")
107:        };
108:        lines.push((kind.into(), block.action.clone()));
109:        if let Some(subid) = &subid {
110:            lines.push(("subid".into(), subid.clone()));
111:        }
112:        if let Some(args_schema) = args_schema {
113:            let value = if kind == "signal" {
114:                // Signals carry their payload as the event's input payload too.
115:                input.clone()
116:            } else {
117:                input
118:            };
119:            for field in described_fields(&args_schema, &value) {
120:                let label = if field.description.is_empty() {
121:                    field.path
122:                } else {
123:                    format!("{} ({})", field.path, field.description)
124:                };
125:                let mut value = field.value;
126:                if value.len() > 512 {
127:                    let mut cut = 512;
128:                    while !value.is_char_boundary(cut) {
129:                        cut -= 1;
130:                    }
131:                    value.truncate(cut);
132:                    value.push('…');
133:                }
134:                lines.push((label, value));
135:            }
136:        }
137:        (lines, subid)
138:    }
139:}
