146:    fn payload_fields(&self, block: &ChainBlockRef) -> serde_json::Map<String, serde_json::Value> {
147:        let mut out = serde_json::Map::new();
148:        if let Some(subid) = self.lines_for(block).1 {
149:            out.insert("subid".into(), subid.into());
150:        }
151:        if let Some(schema) = self.schema(&block.category) {
152:            out.insert("schema_version".into(), schema.version.clone().into());
153:        }
154:        out
